INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('dialogue.police.neighborly.chairman_question', 'scene.police.neighborly', 'dialogue', 'dialogue', 'chairman', 'panteleev', 'Председатель спрашивает участкового после профилактического разговора с жителем; рабочее «вы».', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Не оформляете?', 'Короткая сцена у крыльца пункта: Пантелеев складывает чистый бланк после разговора с жителем.', 'Председатель уточняет, отказался ли участковый от протокола по этому мелкому делу.', 'Проверить границу между устным предупреждением и официальным оформлением.', 'Сохранить краткость вопроса и уважительное множественное обращение.', 'manual/characters/panteleev.md#по-соседски--бумага-подождёт', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('dialogue.police.neighborly.panteleev_answer', 'scene.police.neighborly', 'dialogue', 'dialogue', 'panteleev', 'chairman', 'Участковый отвечает председателю после первого мелкого дела, закрытого профилактикой; рабочее «вы».', NULL, NULL, 'neutral', NULL, NULL, 'dialogue.police.neighborly.chairman_question', 'Протокол успеется. Сегодня человек услышал без него.', 'Та же сцена у крыльца; чистый бланк уже сложен, но не уничтожен.', 'Пантелеев считает, что в этот раз человек понял предупреждение без протокола; повтор заранее не прощён.', 'Объяснить меньшую меру без обещания постоянного снисхождения.', 'Сохранить термин «протокол», противопоставление бумаги услышанному предупреждению и сухой тон.', 'manual/characters/panteleev.md#по-соседски--бумага-подождёт', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('dialogue.school_fears.adult.children_alone', 'scene.school_fears.source_answer', 'dialogue', 'dialogue', 'adult', NULL, 'Председатель и собеседник расследуют школьный слух.', NULL, NULL, 'neutral', 'school_fears.secret=early_home; chairman_choice=children_alone', NULL, NULL, 'Перебоятся. Только дома теперь разговоры не о птицах, а о том, поверят ли ребёнку.', '«Чёрное облако», сцена «Живой источник страшилки»; строка авторского источника 279.', 'Названный свидетель объясняет свой мотив, председатель выбирает ответ.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 1, NULL, 0, 160);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('dialogue.school_fears.adult.early_home_answer', 'scene.school_fears.source_answer', 'dialogue', 'dialogue', 'adult', NULL, 'Председатель и собеседник расследуют школьный слух.', NULL, NULL, 'neutral', 'school_fears.secret=early_home', NULL, NULL, 'Моего ребёнка до темноты домой не загнать. Пришлось приплести крышу: облако, мол, её выберет. Один вечер помогло. Назавтра про это знала половина школы.', '«Чёрное облако», сцена «Живой источник страшилки»; строка авторского источника 249.', 'Названный свидетель объясняет свой мотив, председатель выбирает ответ.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 1, NULL, 0, 40);
