INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('dialogue.school_fears.adult.stop_rumor', 'scene.school_fears.source_answer', 'dialogue', 'dialogue', 'adult', NULL, 'Председатель и собеседник расследуют школьный слух.', NULL, NULL, 'neutral', 'school_fears.secret=early_home; chairman_choice=stop_rumor', NULL, NULL, 'Скажу как было. Засветло домой можно звать и без колдовства.', '«Чёрное облако», сцена «Живой источник страшилки»; строка авторского источника 278.', 'Названный свидетель объясняет свой мотив, председатель выбирает ответ.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 1, NULL, 0, 150);
