INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('dialogue.school_fears.teacher.request', 'scene.school_fears.teacher_opening', 'dialogue', 'dialogue', 'teacher', NULL, 'Председатель и собеседник расследуют школьный слух.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Говорят, это всё от нашей колдуньи. Только никто у неё не был. Разберитесь, откуда взялась страшилка.', '«Чёрное облако», сцена «Чёрное облако пришло в школу»; строка авторского источника 200.', 'Учитель приносит слух и просьбу разобраться.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 1, NULL, 0, 50);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('dialogue.school_fears.witch.bad_joke', 'scene.school_fears.witch_account', 'dialogue', 'dialogue', 'witch', NULL, 'Председатель и собеседник расследуют школьный слух.', NULL, NULL, 'neutral', 'school_fears.secret=bad_joke', NULL, NULL, 'Сказала взрослому: стая выберет, где шумнее всего. Думала, взрослый услышит шутку. Дети услышали правило. Здесь половина слов моя.', '«Чёрное облако», сцена «Что сказала колдунья»; строка авторского источника 229.', 'Колдунья раскрывает или уточняет источник слуха.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 1, NULL, 0, 50);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('dialogue.school_fears.witch.borrowed_name', 'scene.school_fears.witch_account', 'dialogue', 'dialogue', 'witch', NULL, 'Председатель и собеседник расследуют школьный слух.', NULL, NULL, 'neutral', 'school_fears.secret=borrowed_name', NULL, NULL, 'Моё имя там есть, моих слов нет. Вот кто рассказывает про облако: {addressee}. Спросите, откуда взялось предупреждение.', '«Чёрное облако», сцена «Что сказала колдунья»; строка авторского источника 227.', 'Колдунья называет закреплённого школьника, известного ей пересказом; его признание ещё не получено.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 2, NULL, 0, 30);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('dialogue.school_fears.witch.children_alone', 'scene.school_fears.witch_account', 'dialogue', 'dialogue', 'witch', NULL, 'Председатель и собеседник расследуют школьный слух.', NULL, NULL, 'neutral', 'school_fears.secret=retelling|bad_joke; chairman_choice=children_alone', NULL, NULL, 'Перебоятся. Только старшие уже решили выяснить, кто боится неправильно.', '«Чёрное облако», сцена «Что сказала колдунья»; строка авторского источника 271.', 'Колдунья раскрывает или уточняет источник слуха.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 1, NULL, 0, 140);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('dialogue.school_fears.witch.early_home', 'scene.school_fears.witch_account', 'dialogue', 'dialogue', 'witch', NULL, 'Председатель и собеседник расследуют школьный слух.', NULL, NULL, 'neutral', 'school_fears.secret=early_home', NULL, NULL, 'Я сказала про старые деревья. А вот кто это слышал: {addressee}. Крыша выросла позже. Спросите, зачем она понадобилась.', '«Чёрное облако», сцена «Что сказала колдунья»; строка авторского источника 228.', 'Колдунья называет сохранённого взрослого источника слуха, а не случайного прохожего.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 2, NULL, 0, 40);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('dialogue.school_fears.witch.no_extra_fear', 'scene.school_fears.witch_account', 'dialogue', 'dialogue', 'witch', NULL, 'Председатель и собеседник расследуют школьный слух.', NULL, NULL, 'neutral', 'school_fears.secret=retelling|bad_joke', NULL, NULL, 'Пускай взрослые думают, что я знаю лишнее. Детям лишнего бояться незачем.', '«Чёрное облако», сцена «Что сказала колдунья»; строка авторского источника 230.', 'Колдунья раскрывает или уточняет источник слуха.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 1, NULL, 0, 60);
