INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('dialogue.school_fears.witch.retelling_tower', 'scene.school_fears.witch_account', 'dialogue', 'dialogue', 'witch', NULL, 'Председатель и собеседник расследуют школьный слух.', NULL, NULL, 'neutral', 'school_fears.secret=retelling; church_exists', NULL, NULL, 'Я сказала соседке: к вечеру птица соберётся у старых деревьев. Кладбище добавила она, колокольню — чей-то отец, вашу крышу — школьник. Хорошая история: всё село строило.', '«Чёрное облако», сцена «Что сказала колдунья»; строка авторского источника 225.', 'Колдунья раскрывает или уточняет источник слуха.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('dialogue.school_fears.witch.source_observes', 'scene.school_fears.witch_account', 'dialogue', 'dialogue', 'witch', NULL, 'Председатель и собеседник расследуют школьный слух.', NULL, NULL, 'neutral', 'school_fears.secret=retelling|bad_joke; chairman_choice=source_observes', NULL, NULL, 'Детям покажу. Только чудес не заказывайте: птица председателю не подчиняется.', '«Чёрное облако», сцена «Что сказала колдунья»; строка авторского источника 268.', 'Колдунья раскрывает или уточняет источник слуха.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 1, NULL, 0, 110);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('dialogue.school_fears.witch.stop_rumor', 'scene.school_fears.witch_account', 'dialogue', 'dialogue', 'witch', NULL, 'Председатель и собеседник расследуют школьный слух.', NULL, NULL, 'neutral', 'school_fears.secret=retelling|bad_joke; chairman_choice=stop_rumor', NULL, NULL, 'Запретить взрослым додумывать? Вот это настоящее колдовство.', '«Чёрное облако», сцена «Что сказала колдунья»; строка авторского источника 270.', 'Колдунья раскрывает или уточняет источник слуха.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 1, NULL, 0, 130);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('dialogue.school_fears.witch.teacher_observes', 'scene.school_fears.witch_account', 'dialogue', 'dialogue', 'witch', NULL, 'Председатель и собеседник расследуют школьный слух.', NULL, NULL, 'neutral', 'school_fears.secret=retelling|bad_joke; chairman_choice=teacher_observes', NULL, NULL, 'Пусть смотрит до посадки и считает не птиц, а сколько раз собьётся.', '«Чёрное облако», сцена «Что сказала колдунья»; строка авторского источника 269.', 'Колдунья раскрывает или уточняет источник слуха.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 1, NULL, 0, 120);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('quest.quest_story_bird_cloud.body', 'scene.school_fears.teacher_opening', 'quest', 'journal', NULL, NULL, NULL, NULL, NULL, 'neutral', 'chairman_choice=accept', NULL, NULL, 'Установить, откуда взялась страшилка о вечернем птичьем облаке.', '«Чёрное облако»: запись тетради появляется после принятия просьбы учителя.', 'Назвать расследуемый источник слуха, не число обязательных разговоров.', 'Дать игроку понятную цель одной строкой.', 'Не подменять цель счётчиком опрошенных жителей.', 'manual/texts/school-fears-bird-scenes.md', 1, NULL, 0, 100);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.empty_school.opening.nobody_to_ask', 'scene.development.empty_school', 'scene', 'dialogue', 'parent', 'chairman', 'Родитель показывает председателю готовую, но пустую школу.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Стены готовы. Парты готовы. Дети тоже — вон, каждый день проверяют. Только спросить им пока некого.', 'Школа построена; класс открыт, дети собрались за окном, учителя ещё нет.', 'Постройка сама по себе не начинает обучение.', 'Показать следующий человеческий дефицит после успешной стройки без упрёка игроку.', 'Сохранить тройной повтор «готовы» и финальный оборот «спросить некого».', 'manual/texts/development-quests-era-i.md#пустая-школа', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.empty_school.thought.ask_district', 'scene.development.empty_school', 'scene', 'narration', 'chairman', NULL, 'Председатель формулирует следующий шаг.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.empty_school.opening.nobody_to_ask', 'Школа без учителя — ещё одна пустая изба. Нужно просить район и готовить жильё.', 'После слов родителя; внутренняя мысль председателя у пустого учительского стола.', 'Для работы школы нужны учитель и жильё для специалиста.', 'Назвать организационную задачу без разыгрывания заявки отдельной сценой.', 'Сохранить образ пустой избы и два действия: просить район, готовить жильё.', 'manual/texts/development-quests-era-i.md#пустая-школа', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.evening_place.opening.accordion', 'scene.development.evening_place', 'scene', 'dialogue', 'resident_second', NULL, 'Второй житель отвечает первому в споре.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.evening_place.opening.chess', 'За баяном тоже. И обе.', 'Сразу после довода о шахматах.', 'Баян занимает обе руки и потому не хуже соответствует их практическому доводу.', 'Ответить тёплой словесной пикировкой без превращения спорщиков в глупцов.', 'Сохранить две короткие фразы и отдельное «И обе».', 'manual/texts/development-quests-era-i.md#куда-пойти-вечером', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.evening_place.opening.chess', 'scene.development.evening_place', 'scene', 'dialogue', 'resident_first', NULL, 'Первый житель спорит со вторым о занятии для зимних вечеров.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'За шахматами руки заняты.', 'В кабинете двое жителей предлагают разные способы занять долгие зимние вечера.', 'Шахматы мешают пустой ссоре, потому что требуют внимания и занимают руки.', 'Начать серьёзный спор коротким практическим доводом.', 'Сохранить краткость и слово «руки».', 'manual/texts/development-quests-era-i.md#куда-пойти-вечером', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.evening_place.opening.where_to_sit', 'scene.development.evening_place', 'scene', 'dialogue', 'chairman', NULL, 'Председатель подводит итог спору двух жителей.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.evening_place.opening.accordion', 'Значит, сперва найдём, где вам обоим сесть.', 'После двух доводов; оба предложения требуют общего помещения.', 'Прежде выбора занятий селу нужно место для совместных вечеров.', 'Перевести спор характеров в общую хозяйственную задачу.', 'Сохранить примиряющее «вам обоим» и не выбирать между шахматами и баяном.', 'manual/texts/development-quests-era-i.md#куда-пойти-вечером', 1, NULL, 0, 30);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.first_bath_firing.opening.half_minute', 'scene.development.first_bath_firing', 'scene', 'dialogue', 'chairman', 'stoker', 'Председатель отвечает жителю у печи.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.first_bath_firing.opening.speech_length', 'Тогда речь будет на полминуты.', 'Председатель складывает приготовленный лист речи вдвое.', 'Председатель предпочитает короткое открытие делу и ожиданию жителей.', 'Закрыть обмен самоиронией председателя.', 'Сохранить краткость и «полминуты»; не делать речь пятиминутной вопреки ответу.', 'manual/texts/development-quests-era-i.md#первая-топка', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.first_bath_firing.opening.speech_length', 'scene.development.first_bath_firing', 'scene', 'dialogue', 'stoker', 'chairman', 'Житель у печи просит председателя выиграть время короткой речью.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Речь у вас на сколько? Если на пять минут — как раз вода дойдёт. Мы топили на банный день, а село пришло на банную минуту.', 'В первый банный день пришло почти всё село, а первая вода ещё не нагрелась.', 'Нужны ещё пять минут: баня исправна, но одновременный наплыв оказался больше расчёта.', 'Превратить техническую задержку в тёплую шутку и сохранить достоинство всех участников.', 'Сохранить игру «банный день — банная минута» и практический вопрос о длине речи.', 'manual/texts/development-quests-era-i.md#первая-топка', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.first_club_tv_viewing.club_head_hold', 'scene.development.first_club_tv_viewing', 'scene', 'dialogue', 'club_head', 'antenna_adjuster', 'Заведующий клубом даёт человеку у антенны окончательную команду.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.first_club_tv_viewing.club_head_many_chairmen', 'Стой! Вот теперь не трогай.', 'Первый общий просмотр; на экране наконец удержалось ясное изображение.', 'Текущее положение антенны подходит, менять его больше не надо.', 'Завершить настройку и дать залу естественно стихнуть.', 'Сохранить две короткие команды и момент окончательного успеха.', 'manual/texts/development-quests-later-eras.md#председателей-полный-зал', 1, NULL, 0, 40);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.first_club_tv_viewing.club_head_many_chairmen', 'scene.development.first_club_tv_viewing', 'scene', 'dialogue', 'club_head', NULL, 'Заведующий клубом обращается ко всему залу советчиков.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.first_club_tv_viewing.viewer_second_back', 'По одному, товарищи. Антенна у нас одна, а председателей у неё — полный зал.', 'Первый общий просмотр; зал одновременно советует человеку у антенны. При переводе допустим местный эквивалент «начальников».', 'У одной антенны оказалось слишком много добровольных руководителей.', 'Остановить многоголосицу тёплой шуткой без высмеивания жителей.', 'Сохранить одну антенну, полный зал добровольных начальников и обращение к группе; должность можно локализовать по смыслу.', 'manual/texts/development-quests-later-eras.md#председателей-полный-зал', 1, NULL, 0, 30);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.first_club_tv_viewing.viewer_first_more_right', 'scene.development.first_club_tv_viewing', 'scene', 'dialogue', 'viewer_first', 'antenna_adjuster', 'Первый случайный взрослый зритель советует другому посетителю у антенны.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Ещё вправо!', 'Первый общий просмотр в клубе; изображение плывёт, человек у антенны ждёт команды.', 'Антенну надо ещё немного повернуть вправо.', 'Начать добросовестный многоголосый совет зала.', 'Сохранить краткую громкую команду и направление.', 'manual/texts/development-quests-later-eras.md#председателей-полный-зал', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.first_club_tv_viewing.viewer_second_back', 'scene.development.first_club_tv_viewing', 'scene', 'dialogue', 'viewer_second', 'antenna_adjuster', 'Второй случайный взрослый зритель сразу поправляет совет первого.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.first_club_tv_viewing.viewer_first_more_right', 'Не вправо — обратно. Там лицо было.', 'Первый общий просмотр в клубе; на экране на мгновение появилось различимое лицо.', 'Предыдущее положение антенны давало более понятное изображение.', 'Создать смешное из противоречащих добросовестных советов, не из технической глупости.', 'Сохранить поправку направления и конкретный признак изображения — лицо.', 'manual/texts/development-quests-later-eras.md#председателей-полный-зал', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.first_lesson.opening.all_present', 'scene.development.first_lesson', 'scene', 'dialogue', 'teacher', NULL, 'Учитель обращается к классу и замечает ребёнка за окном.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'В списке на одного больше, чем за партами. Зато за окном одна макушка. Значит, все на месте.', 'Первое школьное утро; одно место пустует, над нижним краем окна видна макушка.', 'Робкий ребёнок тоже пришёл, хотя ещё не сел за парту.', 'Показать наблюдательность и доброту учителя без публичного оклика ребёнка.', 'Сохранить счёт списка, парт и одной макушки; не добавлять смех класса.', 'manual/texts/development-quests-era-i.md#первый-урок', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.first_loudspeaker_broadcast.club_voice_test', 'scene.development.first_loudspeaker_broadcast', 'scene', 'dialogue', 'club_voice', NULL, 'Участник проверки обращается через радиоузел ко всем покрытым дворам.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Проверка. Раз, два. Если слышно — проверка закончена.', 'Голос идёт из клуба через впервые включённые уличные громкоговорители.', 'Короткий звуковой тест подтверждает работу односторонней сети.', 'Дать узнаваемую проверочную фразу без агитации и отдельного диктора.', 'Сохранить счёт «раз, два» и условие слышимости.', 'manual/texts/development-quests-later-eras.md#через-улицу', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.first_loudspeaker_broadcast.resident_one_way', 'scene.development.first_loudspeaker_broadcast', 'scene', 'dialogue', 'resident', NULL, 'Житель шутливо отвечает далёкому голосу у своего двора.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.first_loudspeaker_broadcast.club_voice_test', 'Нам слышно. Теперь бы из клуба услышали, что нам слышно.', 'У одного из самых дальних фактически покрытых дворов; ответ не может дойти обратно.', 'Громкоговоритель слышен, но обратной связи у него нет.', 'Маленькой шуткой показать односторонность системы без жалобы.', 'Сохранить повтор «слышно/услышали» и множественное «нам»; не превращать реплику в требование телефона.', 'manual/texts/development-quests-later-eras.md#через-улицу', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.first_night_pasture.groom_count_again', 'scene.development.first_night_pasture', 'scene', 'dialogue', 'groom', 'older_student', 'Конюх спокойно отвечает старшему школьнику.', NULL, NULL, 'neutral', 'Фактический конюх пришёл проводить табун.', NULL, 'scene.development.first_night_pasture.older_student_if_miscalculate', 'Тогда считайте ещё раз. Ночь длинная, а табун никуда не торопится.', 'У ворот перед первым ночным; завершение наставления конюха.', 'Ошибку можно исправить повторным пересчётом; спешки нет.', 'Снять тревогу, не снимая ответственности.', 'Сохранить спокойный хозяйственный юмор и отсутствие опасности.', 'manual/texts/development-quests-era-i.md#первое-ночное', 1, NULL, 0, 30);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.first_night_pasture.groom_count_now', 'scene.development.first_night_pasture', 'scene', 'dialogue', 'groom', 'older_student', 'Конюх передаёт старшему школьнику ответственность за табун.', NULL, NULL, 'neutral', 'Фактический конюх пришёл проводить табун.', NULL, NULL, 'Утром приведёте всех. Считать лучше сейчас, пока каждая перед глазами.', 'У ворот перед первым ночным; говорит фактический конюх, если пришёл проводить.', 'Сначала надо пересчитать лошадей, чтобы утром вернуть весь табун.', 'Показать ответственность через простое выполнимое наставление.', 'Сохранить форму множественного числа и образ каждой лошади перед глазами; не произносить число табуна.', 'manual/texts/development-quests-era-i.md#первое-ночное', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.first_night_pasture.older_student_if_miscalculate', 'scene.development.first_night_pasture', 'scene', 'dialogue', 'older_student', 'groom', 'Старший школьник уточняет у конюха, что делать при ошибке.', NULL, NULL, 'neutral', 'Фактический конюх пришёл проводить табун.', NULL, 'scene.development.first_night_pasture.groom_count_now', 'А если собьёмся?', 'У ворот перед первым ночным; говорит фактически выбранный старший школьник.', 'Школьник допускает, что при пересчёте можно ошибиться.', 'Дать ребёнку задать разумный вопрос без трусости и инфантильности.', 'Сохранить краткость и множественное число.', 'manual/texts/development-quests-era-i.md#первое-ночное', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.first_night_pasture.older_student_trusted_herd', 'scene.development.first_night_pasture', 'scene', 'dialogue', 'older_student', NULL, 'Старший школьник говорит товарищам у костра о непривычном доверии взрослых.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.first_night_pasture.student_our_horse', 'Дома сейчас велели бы спать. А тут велели не спать — и ещё доверили всех лошадей.', 'Позже у костра; старший школьник ещё раз смотрит на фактический табун.', 'Ночное отличается от обычной детской жизни свободой и настоящей ответственностью.', 'Закончить сцену чувством заслуженного доверия.', 'Сохранить повтор «велели» и соединение свободы с ответственностью; не превращать детей в рабочий ресурс.', 'manual/texts/development-quests-era-i.md#первое-ночное', 1, NULL, 0, 50);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.first_night_pasture.student_our_horse', 'scene.development.first_night_pasture', 'scene', 'dialogue', 'student', NULL, 'Школьник шутит товарищам после того, как лошадь облила ему рукав.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.first_night_pasture.groom_count_again', 'Вот теперь точно наша. Чужая бы постеснялась.', 'На пойме; фактически выбранного школьника облила отряхнувшаяся лошадь.', 'Знакомая колхозная лошадь ведёт себя со своими без церемоний.', 'Дать тёплую шутку из узнавания животного, а не из опасности.', 'Сохранить женский род слов «наша» и «чужая»: они относятся к лошади, не к говорящему.', 'manual/texts/development-quests-era-i.md#первое-ночное', 1, NULL, 0, 40);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.first_wall_newspaper.chairman_what_from_me', 'scene.development.first_wall_newspaper', 'scene', 'dialogue', 'chairman', 'komsorg', 'Председатель уточняет у комсорга границу своего участия.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.first_wall_newspaper.komsorg_large_then_good', 'А что от меня?', 'У стенда избы-читальни; фиксированная реплика председателя без выбора.', 'Председатель спрашивает, какая помощь нужна от него.', 'Подвести к делегированию содержания стенгазеты.', 'Сохранить краткость и отсутствие начальственного тона.', 'manual/texts/development-quests-era-i.md#первая-полоса', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.first_wall_newspaper.komsorg_deeds', 'scene.development.first_wall_newspaper', 'scene', 'dialogue', 'komsorg', 'chairman', 'Комсорг оставляет редакционную работу ячейке, а председателю — реальные дела.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.first_wall_newspaper.chairman_what_from_me', 'Стенд уже есть. Дальше от вас — дела. Про них место найдём.', 'У готовой первой полосы; говорит действующий комсорг.', 'Председателю не надо писать заметки: его дела дадут материал ячейке.', 'Закрыть сцену ясным делегированием без лести.', 'Сохранить двусмысленную связь «дела — место в стенгазете»; не делать председателя редактором.', 'manual/texts/development-quests-era-i.md#первая-полоса', 1, NULL, 0, 30);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.first_wall_newspaper.komsorg_large_then_good', 'scene.development.first_wall_newspaper', 'scene', 'dialogue', 'komsorg', 'chairman', 'Комсорг показывает председателю первую полосу ячейки.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Сначала написали крупно, чтобы все увидели. Теперь придётся написать хорошо, чтобы дочитали.', 'У стенда избы-читальни; комсорг замечает, что крупный заголовок потеснил последнюю строку.', 'Заметность первой полосы ещё не означает качества текста.', 'Показать самоиронию и самостоятельную редакторскую ответственность ячейки.', 'Сохранить параллель «крупно/увидели — хорошо/дочитали»; не добавлять лозунг.', 'manual/texts/development-quests-era-i.md#первая-полоса', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.juicy_feed.opening.keep_till_winter', 'scene.development.juicy_feed', 'scene', 'narration', 'chairman', NULL, 'Председатель формулирует задачу после слов скотницы.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.juicy_feed.opening.summer_winter', 'Эту траву надо сохранить до зимы, пока она не пропала.', 'Сразу после реплики скотницы; внутренняя мысль председателя.', 'Надо превратить скоропортящийся летний корм в зимний запас.', 'Закрепить цель квеста, не называя конкретную постройку.', 'Сохранить прямую связь травы, зимы и риска пропажи.', 'manual/texts/development-quests-era-i.md#сочный-корм', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.juicy_feed.opening.summer_winter', 'scene.development.juicy_feed', 'scene', 'dialogue', 'stockwoman', 'chairman', 'Скотница показывает председателю избыток свежей травы.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Сеновал полон. Свежую траву оставим — пропадёт. А зимой корм понадобится.', 'На покосе сеновал уже полон, а нагруженную свежей травой телегу некуда разгружать.', 'Летний избыток нельзя оставить как есть, но зимой тот же корм будет нужен.', 'Назвать хозяйственную проблему без подсказки о силосной траншее.', 'Сохранить последовательность: сеновал полон, трава пропадёт, зимой понадобится корм.', 'manual/texts/development-quests-era-i.md#сочный-корм', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.night_pasture_offer.chairman_who_watches', 'scene.development.night_pasture_offer', 'scene', 'dialogue', 'chairman', 'groom', 'Председатель уточняет у конюха цену предложения.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.night_pasture_offer.groom_night_feed', 'А стеречь кому?', 'У колхозного двора; фиксированная реплика председателя без выбора.', 'Председатель спрашивает, кто будет отвечать за табун ночью.', 'Назвать человеческую цену решения одним коротким вопросом.', 'Сохранить краткость и хозяйственный глагол «стеречь».', 'manual/texts/development-quests-era-i.md#лошади-ночью-едят-сами', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.night_pasture_offer.groom_night_feed', 'scene.development.night_pasture_offer', 'scene', 'dialogue', 'groom', 'chairman', 'Конюх делает председателю хозяйственное предложение.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Днём лошадь в работе, ночью корм у неё под носом. Если табун на пойму вывести, сено останется на потом.', 'У колхозного двора; говорит фактический конюх до выбора школьников.', 'Ночное пастбище сохранит заготовленное сено.', 'Объяснить практическую пользу ночного без обещания бесплатного корма.', 'Сохранить причинную связь работы, ночного выпаса и запаса сена; простая хозяйственная речь.', 'manual/texts/development-quests-era-i.md#лошади-ночью-едят-сами', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.night_pasture_offer.groom_schoolchildren', 'scene.development.night_pasture_offer', 'scene', 'dialogue', 'groom', 'chairman', 'Конюх отвечает председателю и объясняет разницу между взрослой сменой и детским приключением.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.night_pasture_offer.chairman_who_watches', 'Старшим школьникам. Для взрослого это ещё одна смена. Для них — первая ночь, про которую дома не скажут: «Пора спать».', 'У колхозного двора; школьники ещё не выбраны и не показываются.', 'Старшие школьники могут принять ответственное ночное как непривычную свободу, тогда как взрослому это добавило бы смену.', 'Предложить школьников не как дешёвую рабочую силу, а как добровольных участников важного дела.', 'Сохранить противопоставление взрослой смены и первой разрешённой ночи; не обещать конкретных детей.', 'manual/texts/development-quests-era-i.md#лошади-ночью-едят-сами', 1, NULL, 0, 30);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.one_basin.opening.one_basin', 'scene.development.one_basin', 'scene', 'dialogue', 'housewife', 'chairman', 'Хозяйка объясняет председателю бытовой предел домашнего мытья.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Бельё кипятим. Воду греем. Только нас в избе семеро, а таз один: пока последний вымоется, первому опять пора.', 'Заболевший остаётся дома; хозяйка приходит в правление после разговора забрать чистое бельё.', 'Один двор старается соблюдать чистоту, но домашнего таза на большую семью не хватает.', 'Показать нужду в общей бане без изображения болезни и без смеха над бедностью.', 'Сохранить формы «кипятим», «греем» и счёт «семеро — таз один».', 'manual/texts/development-quests-era-i.md#одного-таза-мало', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.one_basin.thought.bath', 'scene.development.one_basin', 'scene', 'narration', 'chairman', NULL, 'Председатель переводит частную нужду в общую задачу.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.one_basin.opening.one_basin', 'Для одного двора — таз. Для села нужна баня.', 'После слов хозяйки; внутренняя мысль председателя.', 'Домашнее средство годится одному двору, всему селу нужна общая баня.', 'Сформулировать прямой переход от частного случая к развитию села.', 'Сохранить параллель «для двора — таз; для села — баня».', 'manual/texts/development-quests-era-i.md#одного-таза-мало', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.own_office.opening.sign_first', 'scene.development.own_office', 'scene', 'dialogue', 'shibanov', 'chairman', 'Шибанов просит подпись среди тесноты временного правления.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Ты сперва ему подпиши, потом мне. А то у меня зерно отсыреет раньше, чем у него справка высохнет.', 'В церкви одновременно ждёт посетитель, Шибанов просит подпись, а с потолка капает в кружку.', 'Временное помещение смешивает приём жителей, склад и бумаги.', 'Показать предел старой конторы через рабочую остроту Шибанова.', 'Сохранить порядок «ему — потом мне» и параллель зерна со справкой.', 'manual/texts/development-quests-era-i.md#своя-контора', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.own_office.thought.on_laps', 'scene.development.own_office', 'scene', 'narration', 'chairman', NULL, 'Председатель оценивает тесноту правления.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.own_office.opening.sign_first', 'Тут уже не тесно. Тут хозяйство друг у друга на коленях сидит.', 'После реплики Шибанова; внутренняя мысль председателя.', 'Разные функции правления физически мешают друг другу.', 'Подвести к собственной конторе без перечисления механических выгод.', 'Сохранить образ хозяйства, сидящего друг у друга на коленях.', 'manual/texts/development-quests-era-i.md#своя-контора', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.radio_node_test.chairman_test_enough', 'scene.development.radio_node_test', 'scene', 'dialogue', 'chairman', 'club_head', 'Председатель оценивает доклад заведующего как достаточный для проверки.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.radio_node_test.club_head_room_hears', 'Для проверки достаточно.', 'В клубе у контрольного динамика; фиксированная реплика председателя.', 'Работу самого радиоузла уже можно признать проверенной.', 'Отделить техническую проверку от следующей задачи охвата.', 'Сохранить сухую краткость.', 'manual/texts/development-quests-later-eras.md#слышно-пока-только-здесь', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.radio_node_test.club_head_room_hears', 'scene.development.radio_node_test', 'scene', 'dialogue', 'club_head', 'chairman', 'Заведующий докладывает председателю результат первой проверки.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Радиоузел работает. Пока нас слышит только эта комната.', 'В клубе у контрольного динамика; уличные громкоговорители ещё не установлены.', 'Аппаратура исправна, но вещание пока не выходит за пределы комнаты.', 'Честно показать промежуточный результат без преждевременного охвата села.', 'Сохранить термин «радиоузел» и ограничение одной комнатой.', 'manual/texts/development-quests-later-eras.md#слышно-пока-только-здесь', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.radio_node_test.club_head_voice_outside', 'scene.development.radio_node_test', 'scene', 'dialogue', 'club_head', 'chairman', 'Заведующий соглашается с председателем и называет оставшуюся задачу.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.radio_node_test.chairman_test_enough', 'Для проверки — да. Для села придётся решить, куда вынести голос.', 'В клубе у контрольного динамика; последняя реплика открывает смысл размещения громкоговорителей.', 'Чтобы вещание услышало село, надо выбрать места уличных громкоговорителей.', 'Перевести технический успех в решение игрока без маркеров и готового ответа.', 'Сохранить противопоставление «для проверки/для села» и образ вынесенного голоса.', 'manual/texts/development-quests-later-eras.md#слышно-пока-только-здесь', 1, NULL, 0, 30);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.roof_over_head.opening.chests', 'scene.development.roof_over_head', 'scene', 'dialogue', 'housewife', 'chairman', 'Хозяйка показывает председателю тесноту своего двора.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Мы потеснимся. Куда денемся. Только сундуки уже спят лучше нас.', 'У крыльца целого дома стоят два сундука; за дверью разместились две семьи.', 'Семья готова терпеть тесноту, но жилого места уже объективно не хватает.', 'Показать нужду в жилье через тёплую бытовую шутку, а не жалобу.', 'Сохранить три короткие фразы и образ сундуков, которым просторнее, чем людям.', 'manual/texts/development-quests-era-i.md#крыша-над-головой', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.roof_over_head.thought.courtesy', 'scene.development.roof_over_head', 'scene', 'narration', 'chairman', NULL, 'Председатель осмысливает услышанное.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.roof_over_head.opening.chests', 'Дом один, семей две. На одной вежливости зиму не проживёшь.', 'Сразу после реплики хозяйки; внутренняя мысль председателя.', 'Добрые отношения не заменяют второго жилья.', 'Сформулировать проблему, не подсказывая тип будущей постройки.', 'Сохранить счёт «дом один, семей две» и противопоставление вежливости зиме.', 'manual/texts/development-quests-era-i.md#крыша-над-головой', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.second_phone_subscriber.postman_brought_note', 'scene.development.second_phone_subscriber', 'scene', 'dialogue', 'postman', 'worker', 'Почтальон подтверждает, что привёз бумажный оригинал уже переданного сообщения.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.second_phone_subscriber.worker_already_told', 'Про неё. Я как раз эту записку и вёз.', 'У второго телефонного абонента; почтальон держит районную записку, адресованную юниту.', 'Почтальон узнаёт в словах работника содержание доставленной бумаги.', 'Показать, что телефон обогнал обычный почтовый маршрут.', 'Сохранить нейтральность по роду и будничное удивление без обиды на новую связь.', 'manual/texts/development-quests-later-eras.md#бумага-пришла-следом', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.second_phone_subscriber.postman_road_shorter', 'scene.development.second_phone_subscriber', 'scene', 'dialogue', 'postman', 'worker', 'Почтальон подводит итог сравнения телефона и почтовой дороги.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.second_phone_subscriber.worker_wire_faster', 'Провод короче дороги. А бумага всё равно пригодится — на ней расписаться можно.', 'У второго телефонного абонента; почтальон отдаёт районную записку под подпись.', 'Телефон быстрее доставки, но подписанный документ сохраняет отдельную функцию.', 'Показать дополнение каналов связи, а не исчезновение почты.', 'Сохранить образ «провод короче дороги» и практическую ценность подписи на бумаге.', 'manual/texts/development-quests-later-eras.md#бумага-пришла-следом', 1, NULL, 0, 40);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.second_phone_subscriber.worker_already_told', 'scene.development.second_phone_subscriber', 'scene', 'dialogue', 'worker', 'postman', 'Работник подключённого юнита узнаёт содержание записки до её вручения.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Если там про завтрашнюю работу, уже передали.', 'Сразу после телефонного звонка; в дверь входит районный почтальон с запиской.', 'Рабочее сообщение уже пришло по телефону раньше бумаги.', 'Одной фразой показать, что связь обогнала дорогу.', 'Сохранить будничность и условное «если там».', 'manual/texts/development-quests-later-eras.md#бумага-пришла-следом', 2, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.second_phone_subscriber.worker_wire_faster', 'scene.development.second_phone_subscriber', 'scene', 'dialogue', 'worker', 'postman', 'Работник первым формулирует очевидный итог встречи телефона с почтой.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.second_phone_subscriber.postman_brought_note', 'Выходит, провод быстрее.', 'У второго телефонного абонента; тот же нынешний работник юнита.', 'Телефон передал содержание раньше, чем почта доставила оригинал.', 'Подготовить ответ почтальона одной естественной репликой.', 'Сохранить простую разговорную формулировку без насмешки над почтой.', 'manual/texts/development-quests-later-eras.md#бумага-пришла-следом', 1, NULL, 0, 30);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.teach_children.opening.who_next', 'scene.development.teach_children', 'scene', 'dialogue', 'parent', 'chairman', 'Родитель спрашивает председателя о дальнейшем обучении детей.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Поправить-то я поправлю. А дальше кто?', 'У крыльца дети пишут мелом на обломке доски; родитель может поправить букву, но не заменить школу.', 'Домашней подсказки недостаточно для постоянного обучения.', 'Поставить взрослый практический вопрос без умиления над детьми.', 'Сохранить противопоставление «я поправлю — а дальше кто».', 'manual/texts/development-quests-era-i.md#учить-детей', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.teach_children.thought.school_not_yet', 'scene.development.teach_children', 'scene', 'narration', 'chairman', NULL, 'Председатель признаёт необходимость школы.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.teach_children.opening.who_next', 'Дети уже доросли. Школа — ещё нет.', 'После вопроса родителя; внутренняя мысль председателя.', 'Возраст детей уже требует школы, которой в селе пока нет.', 'Кратко сформулировать разрыв между жизнью детей и развитием села.', 'Сохранить параллель двух коротких предложений и тире во втором.', 'manual/texts/development-quests-era-i.md#учить-детей', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.winter_crop.opening.all_today', 'scene.development.winter_crop', 'scene', 'dialogue', 'worker', 'chairman', 'Работник говорит председателю после уборки.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Урожай хороший. Только весь почему-то сегодня.', 'После уборки люди сидят у поля; на соседней полосе ещё стоит неубранное зерно.', 'Даже хороший урожай опасен, если вся уборка пришлась на одно короткое окно.', 'Передать усталую хозяйственную досаду одной короткой фразой.', 'Сохранить разрыв после похвалы урожаю и слово «сегодня» как образ узкого окна.', 'manual/texts/development-quests-era-i.md#озимый-клин', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.winter_crop.thought.window', 'scene.development.winter_crop', 'scene', 'narration', 'chairman', NULL, 'Председатель оценивает риск следующего сезона.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.winter_crop.opening.all_today', 'Ещё одно такое окно — и половина останется зимовать в поле.', 'После реплики работника; внутренняя мысль председателя.', 'Повтор того же графика уборки приведёт к потерям в поле.', 'Связать увиденное с необходимостью разнести сроки созревания.', 'Сохранить хозяйственный образ зерна, оставшегося зимовать в поле.', 'manual/texts/development-quests-era-i.md#озимый-клин', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.winter_evenings_opening.chairman_cinema_full', 'scene.development.winter_evenings_opening', 'scene', 'dialogue', 'chairman', 'party_organizer', 'Председатель возражает парторгу фактом уже работающего клуба.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.winter_evenings_opening.party_organizer_reason_to_return', 'Кино собирает полный зал.', 'В работающем клубе; фиксированная реплика председателя без выбора.', 'На кинопоказ жители уже приходят массово.', 'Дать разумное возражение, чтобы квест не начинался с очевидного согласия.', 'Сохранить краткость и полный зал как наблюдение, не числовой порог.', 'manual/texts/development-quests-later-eras.md#клуб-на-всю-зиму', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.winter_evenings_opening.party_organizer_reason_to_return', 'scene.development.winter_evenings_opening', 'scene', 'dialogue', 'party_organizer', 'chairman', 'Парторг обсуждает с председателем недоделанную общую жизнь клуба.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Избу строили, чтобы было куда прийти. Клуб построили — теперь надо, чтобы было зачем возвращаться.', 'В работающем клубе первой зимой Эпохи II; рядом идёт одно настоящее занятие.', 'Одного здания мало: нужна устойчивая причина приходить снова.', 'Не обесценить клуб, а назвать следующий уровень общей жизни.', 'Сохранить параллель «куда прийти/зачем возвращаться» и различие избы и клуба.', 'manual/texts/development-quests-later-eras.md#клуб-на-всю-зиму', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.winter_evenings_opening.party_organizer_winter_longer', 'scene.development.winter_evenings_opening', 'scene', 'dialogue', 'party_organizer', 'chairman', 'Парторг отвечает председателю без отрицания успеха кино.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.winter_evenings_opening.chairman_cinema_full', 'На один вечер. А зима длиннее одной картины.', 'В работающем клубе; парторг называет предел разового кинопоказа.', 'Кино заполняет один вечер, но не создаёт программу на весь зимний сезон.', 'Свести задачу к устойчивому циклу занятий, а не к порогу посещаемости.', 'Сохранить противопоставление одного вечера и длинной зимы; «картина» означает фильм.', 'manual/texts/development-quests-later-eras.md#клуб-на-всю-зиму', 1, NULL, 0, 30);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.winter_evenings_result.chairman_crowded', 'scene.development.winter_evenings_result', 'scene', 'dialogue', 'chairman', 'party_organizer', 'Председатель уточняет наблюдение нынешнего парторга.', NULL, NULL, 'neutral', 'Должность парторга занята.', NULL, 'scene.development.winter_evenings_result.party_organizer_chairs_in_aisle', 'Значит, тесно стало?', 'После занятия; реплика пропускается вместе с первой, если парторга нет.', 'Председатель спрашивает, означает ли движение стульев переполненность.', 'Подвести к человеческому итогу одним коротким вопросом.', 'Сохранить разговорное «тесно стало».', 'manual/texts/development-quests-later-eras.md#стулья-в-проходе', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.winter_evenings_result.party_organizer_chairs_in_aisle', 'scene.development.winter_evenings_result', 'scene', 'dialogue', 'party_organizer', 'chairman', 'Нынешний парторг подводит председателю итог зимней программы.', NULL, 'winter_evenings_result.party_organizer_chairs_gender', 'male', 'Должность парторга занята мужчиной.', NULL, NULL, 'В начале зимы стулья в зал носил. Теперь из прохода выношу.', 'После фактически завершённого зимнего цикла; нынешний парторг пропускает выходящих после занятия.', 'В начале сезона людей не хватало, теперь лишние стулья мешают проходу.', 'Показать успех через изменившееся бытовое действие, а не отчётную цифру.', 'Сохранить мужскую форму «носил», контраст направления стульев и отсутствие чисел.', 'manual/texts/development-quests-later-eras.md#стулья-в-проходе', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.winter_evenings_result.party_organizer_chairs_in_aisle_female', 'scene.development.winter_evenings_result', 'scene', 'dialogue', 'party_organizer', 'chairman', 'Нынешний парторг подводит председателю итог зимней программы.', NULL, 'winter_evenings_result.party_organizer_chairs_gender', 'female', 'Должность парторга занята женщиной.', NULL, NULL, 'В начале зимы стулья в зал носила. Теперь из прохода выношу.', 'После фактически завершённого зимнего цикла; нынешний парторг — женщина, она пропускает выходящих после занятия.', 'В начале сезона людей не хватало, теперь лишние стулья мешают проходу.', 'Показать успех через изменившееся бытовое действие, а не отчётную цифру.', 'Сохранить женскую форму «носила», контраст направления стульев и отсутствие чисел.', 'manual/texts/development-quests-later-eras.md#стулья-в-проходе', 1, NULL, 0, 11);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.development.winter_evenings_result.result_people_come', 'scene.development.winter_evenings_result', 'scene', 'dialogue', 'result_speaker', 'chairman', 'Парторг отвечает председателю; при свободной роли заведующий клубом произносит тот же итог самостоятельно.', NULL, NULL, 'neutral', NULL, NULL, 'scene.development.winter_evenings_result.chairman_crowded', 'Значит, приходят. С теснотой заведующий разберётся.', 'Итог зимней программы; при свободной роли парторга говорит действующий заведующий клубом без двух предыдущих реплик.', 'Главный результат — люди приобрели привычку приходить; бытовую тесноту решит заведующий.', 'Отделить социальный результат от ежедневного управления клубом.', 'Сохранить повтор «значит» в полной трёхрепличной версии и делегирование заведующему; строка должна работать самостоятельно.', 'manual/texts/development-quests-later-eras.md#стулья-в-проходе', 1, NULL, 0, 30);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.district.failure_explanation.answer.equipment', 'scene.district.failure_explanation', 'scene', 'choice', 'chairman', NULL, 'Председатель называет фактическому лицу района одну причину провала; рабочее «вы».', 'answer', NULL, 'neutral', 'Техника была и фактически остановилась в проваленном году.', NULL, NULL, 'Техника подвела во время работ. Потерянное время не вернули.', 'Условный вариант ответа; метка причины equipment; адресат — выбранное лицо района.', 'Председатель объясняет годовой провал одной из подтверждённых причин.', 'Дать игроку честный выбор причины без изменения уже рассчитанного результата года.', 'Сохранить метку equipment, правдивость условия и отсутствие обвинения отдельного жителя.', 'manual/characters/district-faces.md#объяснение-провала-району', 1, NULL, 0, 22);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.district.failure_explanation.answer.limit', 'scene.district.failure_explanation', 'scene', 'choice', 'chairman', NULL, 'Председатель называет фактическому лицу района одну причину провала; рабочее «вы».', 'answer', NULL, 'neutral', 'Реальный лимит помешал исполнению в проваленном году.', NULL, NULL, 'Лимита не хватило на работу. План от этого меньше не стал.', 'Условный вариант ответа; метка причины limit; адресат — выбранное лицо района.', 'Председатель объясняет годовой провал одной из подтверждённых причин.', 'Дать игроку честный выбор причины без изменения уже рассчитанного результата года.', 'Сохранить метку limit, правдивость условия и отсутствие обвинения отдельного жителя.', 'manual/characters/district-faces.md#объяснение-провала-району', 1, NULL, 0, 23);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.district.failure_explanation.answer.people', 'scene.district.failure_explanation', 'scene', 'choice', 'chairman', NULL, 'Председатель называет фактическому лицу района одну причину провала; рабочее «вы».', 'answer', NULL, 'neutral', 'В нужный срок была нехватка работников в проваленном году.', NULL, NULL, 'Людей на эту работу не хватило. Решение, куда их поставить, было моё.', 'Условный вариант ответа; метка причины people; адресат — выбранное лицо района.', 'Председатель объясняет годовой провал одной из подтверждённых причин.', 'Дать игроку честный выбор причины без изменения уже рассчитанного результата года.', 'Сохранить метку people, правдивость условия и отсутствие обвинения отдельного жителя.', 'manual/characters/district-faces.md#объяснение-провала-району', 1, NULL, 0, 21);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.district.failure_explanation.answer.unfinished', 'scene.district.failure_explanation', 'scene', 'choice', 'chairman', NULL, 'Председатель называет фактическому лицу района одну причину провала; рабочее «вы».', 'answer', NULL, 'neutral', 'К сроку осталась незаконченная работа; из четырёх конкретных причин доступны не более трёх в проваленном году.', NULL, NULL, 'Не успели закончить вовремя. Это и записывайте.', 'Условный вариант ответа; метка причины unfinished; адресат — выбранное лицо района.', 'Председатель объясняет годовой провал одной из подтверждённых причин.', 'Дать игроку честный выбор причины без изменения уже рассчитанного результата года.', 'Сохранить метку unfinished, правдивость условия и отсутствие обвинения отдельного жителя.', 'manual/characters/district-faces.md#объяснение-провала-району', 1, NULL, 0, 24);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.district.failure_explanation.answer.weather', 'scene.district.failure_explanation', 'scene', 'choice', 'chairman', NULL, 'Председатель называет фактическому лицу района одну причину провала; рабочее «вы».', 'answer', NULL, 'neutral', 'Погодное окно действительно сорвало работу в проваленном году.', NULL, NULL, 'Погода задержала работу. Время потом не наверстали.', 'Условный вариант ответа; метка причины weather; адресат — выбранное лицо района.', 'Председатель объясняет годовой провал одной из подтверждённых причин.', 'Дать игроку честный выбор причины без изменения уже рассчитанного результата года.', 'Сохранить метку weather, правдивость условия и отсутствие обвинения отдельного жителя.', 'manual/characters/district-faces.md#объяснение-провала-району', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.district.failure_explanation.opening.karasev', 'scene.district.failure_explanation', 'scene', 'dialogue', 'karasev', 'chairman', 'Именное лицо района спрашивает председателя о проваленном плане; рабочее «вы».', NULL, NULL, 'neutral', 'В состоянии сцены выбран district_face=karasev.', NULL, NULL, 'В сводке за {failed_year} год недостача. Мне ведь придётся что-то написать. Что именно?', 'Встреча после провала плана за {failed_year} год; говорит Геннадий Маркович Карасёв.', 'Район просит председателя назвать причину провала годового плана.', 'Открыть выбор причин без готового обвинения.', 'Сохранить год из состояния сцены и голос данного лица; не брать текущий год.', 'manual/characters/district-faces.md#объяснение-провала-району', 1, NULL, 0, 12);
