INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.district.failure_explanation.opening.polushkina', 'scene.district.failure_explanation', 'scene', 'dialogue', 'polushkina', 'chairman', 'Именное лицо района спрашивает председателя о проваленном плане; рабочее «вы».', NULL, NULL, 'neutral', 'В состоянии сцены выбран district_face=polushkina.', NULL, NULL, 'В отчёте за {failed_year} год план не выполнен. В бланке есть строка для причины. Что туда вписать?', 'Встреча после провала плана за {failed_year} год; говорит Зоя Викторовна Полушкина.', 'Район просит председателя назвать причину провала годового плана.', 'Открыть выбор причин без готового обвинения.', 'Сохранить год из состояния сцены и голос данного лица; не брать текущий год.', 'manual/characters/district-faces.md#объяснение-провала-району', 1, NULL, 0, 14);
