INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.district.failure_explanation.opening.zhernova', 'scene.district.failure_explanation', 'scene', 'dialogue', 'zhernova', 'chairman', 'Именное лицо района спрашивает председателя о проваленном плане; рабочее «вы».', NULL, NULL, 'neutral', 'В состоянии сцены выбран district_face=zhernova.', NULL, NULL, 'План за {failed_year} год не выполнен. Я вижу цифры. Теперь назовите причину.', 'Встреча после провала плана за {failed_year} год; говорит Серафима Прокофьевна Жернова.', 'Район просит председателя назвать причину провала годового плана.', 'Открыть выбор причин без готового обвинения.', 'Сохранить год из состояния сцены и голос данного лица; не брать текущий год.', 'manual/characters/district-faces.md#объяснение-провала-району', 1, NULL, 0, 13);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.district.failure_explanation.return.karasev', 'scene.district.failure_explanation', 'scene', 'dialogue', 'karasev', 'chairman', 'Именное лицо района коротко отвечает председателю после выбранной причины; рабочее «вы».', NULL, NULL, 'neutral', 'Выбрана причина; district_face=karasev.', NULL, NULL, 'Запишу. Бумага длиннее разговора.', 'После ответа председателя говорит только Геннадий Маркович Карасёв.', 'Собеседник услышал объяснение, но не подтвердил его истинность.', 'Закрыть разговор коротко, без нового решения и скрытого счётчика.', 'Не менять результат плана и не объявлять, сколько разных причин услышал район.', 'manual/characters/district-faces.md#объяснение-провала-району', 2, NULL, 0, 32);
