INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.ending.village.liquidation.chairman', 'scene.ending.village.liquidation', 'scene', 'dialogue', 'chairman', 'district_rep', 'Председатель отвечает фактически присутствующему собеседнику.', NULL, NULL, 'neutral', 'always', NULL, NULL, 'Село перестанет быть отдельным хозяйством. С каждым двором всё равно придётся говорить.', 'Сцена «Хозяйство ликвидируют». Голос: Председатель. Условие: always.', 'Ликвидация отдельного хозяйства, не исчезновение людей.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие always; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 2, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.ending.village.liquidation.district', 'scene.ending.village.liquidation', 'scene', 'dialogue', 'district_rep', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'always', NULL, NULL, 'Два года подряд жителей меньше сорока. Район принял решение: отдельное хозяйство ликвидировать, земли и оставшиеся дворы присоединить к соседнему. Как люди будут жить дальше, будем решать с каждым двором.', 'Сцена «Хозяйство ликвидируют». Голос: Представитель района. Условие: always.', 'Ликвидация отдельного хозяйства, не исчезновение людей.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие always; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.ending.village.warning_report.district', 'scene.ending.village.warning_report', 'scene', 'dialogue', 'district_rep', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'always', NULL, NULL, 'На этот поворот года население хозяйства — {resident_count}. Если и через год жителей останется меньше сорока, район будет решать вопрос о присоединении села к соседнему хозяйству.', 'Сцена «Сводка района: село убывает». Голос: Представитель района. Условие: always.', 'Первое предупреждение об убыли без решения о ликвидации.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие always; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 2, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.ending.village.warning_rumour.resident', 'scene.ending.village.warning_rumour', 'scene', 'dialogue', 'resident', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'adult_knows_report', NULL, NULL, 'Пустых дворов стало больше. Но в обжитых ещё топят печи.', 'Сцена «Разговоры в селе об убыли». Голос: Житель. Условие: adult_knows_report.', 'Отклик жителя на дошедшую новость.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие adult_knows_report; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.era.first_transition_offer.karasev', 'scene.era.first_transition_offer', 'scene', 'dialogue', 'karasev', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'district_face=karasev', NULL, NULL, 'Привёз предложение района: новый статус, укрупнение, целевые фонды. Третий год вы держите нужный уровень. Ответ теперь за вами.', 'Сцена «Район предлагает переход». Голос: Карасёв. Условие: district_face=karasev.', 'Район предлагает переход; игрок отвечает карточкой.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие district_face=karasev; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 1, NULL, 0, 30);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.era.first_transition_offer.korenev', 'scene.era.first_transition_offer', 'scene', 'dialogue', 'korenev', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'district_face=korenev', NULL, NULL, 'Хозяйство держит нужный уровень третий год. Район предлагает новый статус, укрупнение и целевые фонды. Решение за вами. Но подумайте, кто возьмёт на себя новую работу.', 'Сцена «Район предлагает переход». Голос: Коренев. Условие: district_face=korenev.', 'Район предлагает переход; игрок отвечает карточкой.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие district_face=korenev; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 2, NULL, 0, 10);
