INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.era.first_transition_refusal.polushkina', 'scene.era.first_transition_refusal', 'scene', 'dialogue', 'polushkina', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'district_face=polushkina', NULL, NULL, 'Отказ отмечен. Следующее предложение возможно не раньше чем через три года.', 'Сцена «Отказ от перехода». Голос: Полушкина. Условие: district_face=polushkina.', 'Район фиксирует отказ и срок следующего предложения.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие district_face=polushkina; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 1, NULL, 0, 50);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.era.first_transition_refusal.stozharov', 'scene.era.first_transition_refusal', 'scene', 'dialogue', 'stozharov', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'district_face=stozharov', NULL, NULL, 'Оставайтесь в нынешнем укладе. Район вернётся с предложением не раньше чем через три года.', 'Сцена «Отказ от перехода». Голос: Стожаров. Условие: district_face=stozharov.', 'Район фиксирует отказ и срок следующего предложения.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие district_face=stozharov; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.era.first_transition_refusal.zhernova', 'scene.era.first_transition_refusal', 'scene', 'dialogue', 'zhernova', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'district_face=zhernova', NULL, NULL, 'Отказ внесён в запись. Нынешний порядок сохраняется. Повторить предложение район сможет не раньше чем через три года.', 'Сцена «Отказ от перехода». Голос: Жернова. Условие: district_face=zhernova.', 'Район фиксирует отказ и срок следующего предложения.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие district_face=zhernova; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 1, NULL, 0, 40);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.answer.general', 'scene.family.before_distribution', 'scene', 'choice', 'chairman', 'member', 'Председатель принимает общее правило для всех подходящих дворов.', 'answer', NULL, 'neutral', 'Склад позволяет включить общее правило для дворов у порога минимального пайка.', 'changed', 'scene.family.before_distribution.opening.queue', 'Кто просел до минимума, получит паёк. Не только вы.', 'Второй вариант ответа; виден только если фактический склад может обеспечить общее правило.', 'Помощь по одинаковому правилу всем семьям у порога.', 'Назвать не конкретный двор, а проверяемый общий критерий.', 'Сохранить условность «кто просел до минимума» и противопоставление личной помощи.', 'manual/quests/family-thread.md#разговор-до-выдачи', 2, NULL, 0, 31);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.answer.personal', 'scene.family.before_distribution', 'scene', 'choice', 'chairman', 'member', 'Председатель отвечает конкретному пришедшему взрослому; решение распространяется только на его двор.', 'answer', NULL, 'neutral', NULL, 'changed', 'scene.family.before_distribution.opening.queue', 'Включу паёк вашему двору уже сейчас.', 'Первый вариант ответа, всегда доступен; действие действительно включает паёк одному двору.', 'Личная помощь выбранной семье до общей выдачи.', 'Зафиксировать личное решение, а не обещание на потом.', 'Сохранить «вашему двору» и «сейчас»; не обещать паёк остальным.', 'manual/quests/family-thread.md#разговор-до-выдачи', 2, NULL, 0, 30);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.answer.premium', 'scene.family.before_distribution', 'scene', 'choice', 'chairman', 'member', 'Председатель называет заслуженную, но ещё не выданную премию выбранной семье.', 'answer', NULL, 'neutral', 'У семьи есть реальный заслуживающий премии поступок; премия ещё не выдана.', 'changed', 'scene.family.before_distribution.opening.queue', 'За {real_deed} вашей семье положена премия. Выдадим сейчас.', 'Третий вариант ответа; {real_deed} — грамматически готовое словосочетание после «за», только о фактическом поступке семьи.', 'Премия выдаётся за уже совершённое дело, не как замаскированный паёк.', 'Назвать основание выплаты и принять немедленное решение.', 'Не придумывать заслугу и не опускать основание; подстановка должна согласовываться с предлогом «за».', 'manual/quests/family-thread.md#разговор-до-выдачи', 2, NULL, 0, 32);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.answer.unchanged', 'scene.family.before_distribution', 'scene', 'choice', 'chairman', 'member', 'Председатель отвечает без изменения обычного порядка.', 'answer', NULL, 'neutral', NULL, 'unchanged', 'scene.family.before_distribution.opening.queue', 'До выдачи порядок не меняю.', 'Четвёртый вариант ответа, всегда доступен; семья получает обычную выдачу по действующим правилам.', 'Председатель отказывает в раннем изменении порядка, не отказывая семье в обычной выдаче.', 'Сделать отказ ясным и коротким, без обвинения семьи.', 'Сохранить срок «до выдачи»; не превращать в постоянный отказ в пайке.', 'manual/quests/family-thread.md#разговор-до-выдачи', 2, NULL, 0, 33);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.backdrop', 'scene.family.before_distribution', 'scene', 'backdrop', NULL, NULL, NULL, NULL, NULL, 'neutral', NULL, NULL, NULL, 'Один двор просит помочь сейчас; рядом есть другие, которым не легче.', 'Авторская подложка сцены «До выдачи», игроку не показывается. Семья выбрана из фактической партии.', 'Нужда одного двора ставит вопрос об общем правиле для других дворов.', 'Ограничить разговор четырьмя реальными решениями без голодной трагедии.', 'Не превращать детей в средство давления и не придумывать беду другим дворам.', 'manual/quests/family-thread.md#разговор-до-выдачи', 1, NULL, 0, 1);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.memory.general', 'scene.family.before_distribution', 'scene', 'dialogue', 'memory_member', NULL, 'Доступный взрослый того же двора или родственной ветви вспоминает общее правило после их просьбы.', NULL, NULL, 'neutral', 'Сохранён исход answer.general.', NULL, NULL, 'После нашего разговора паёк пошёл всем.', 'Короткая первая реплика позднего возврата семьи; «всем» означает подходящие дворы, не всех жителей.', 'После обращения семьи помощь стали получать все дворы у порога.', 'Привязать поздний возврат к принятому общему правилу.', 'Сохранить причинную последовательность разговора и решения; не приписывать семье принятие правила.', 'manual/quests/family-thread.md#что-запоминается-для-следующих-сцен', 1, NULL, 0, 51);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.memory.personal', 'scene.family.before_distribution', 'scene', 'dialogue', 'memory_member', NULL, 'Доступный взрослый того же двора или родственной ветви вспоминает личную помощь председателя.', NULL, NULL, 'neutral', 'Сохранён исход answer.personal.', NULL, NULL, 'Вы тогда помогли нашему двору отдельно.', 'Короткая первая реплика позднего возврата семьи, не часть разговора Эпохи I.', 'Председатель помог только этому двору.', 'Привязать поздний возврат к действительно записанному исходу.', 'Сохранить «нашему двору» и «отдельно»; не утверждать помощи другим.', 'manual/quests/family-thread.md#что-запоминается-для-следующих-сцен', 1, NULL, 0, 50);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.memory.premium', 'scene.family.before_distribution', 'scene', 'dialogue', 'memory_member', NULL, 'Доступный взрослый того же двора или родственной ветви вспоминает заслуженную премию.', NULL, NULL, 'neutral', 'Сохранён исход answer.premium.', NULL, NULL, 'Мы тогда получили своё не по просьбе, а за дело.', 'Короткая первая реплика позднего возврата семьи, без новой выплаты.', 'Премия была заработана до просьбы и затем выдана.', 'Сохранить в семейной памяти основание премии, а не вторую награду.', 'Не называть премию подачкой и не обещать повторной выплаты.', 'manual/quests/family-thread.md#что-запоминается-для-следующих-сцен', 1, NULL, 0, 52);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.memory.usual', 'scene.family.before_distribution', 'scene', 'dialogue', 'memory_member', NULL, 'Доступный взрослый того же двора или родственной ветви вспоминает обычную выдачу.', NULL, NULL, 'neutral', 'Выбран answer.unchanged либо срок истёк без разговора.', NULL, NULL, 'Мы тогда дотянули до выдачи своим двором.', 'Короткая первая реплика позднего возврата семьи; срок может истечь вообще без разговора.', 'Семья получила обычную выдачу без ранней помощи.', 'Объединить два пути к одному фактическому исходу.', 'Не подразумевать, что председатель разговаривал с семьёй при вышедшем сроке.', 'manual/quests/family-thread.md#что-запоминается-для-следующих-сцен', 1, NULL, 0, 53);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.opening.bread', 'scene.family.before_distribution', 'scene', 'dialogue', 'member', 'chairman', 'Взрослый член выбранной семьи обращается к председателю с просьбой до очередной выдачи.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'До выдачи мы дотянем. Только дети начали хлеб на завтра считать сегодня.', 'Первое высказывание в кабинете; у выбранной семьи действительно есть ребёнок. Без показа голода и плачущих детей.', 'Семья может дождаться выдачи, но запас уже тревожно мал.', 'Дать человеческую причину просьбы, не обвиняя председателя.', 'Сохранить уверенное «дотянем» и тревогу о завтрашнем хлебе; не усиливать до угрозы голодной смерти.', 'manual/quests/family-thread.md#разговор-до-выдачи', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.opening.queue', 'scene.family.before_distribution', 'scene', 'dialogue', 'member', 'chairman', 'Тот же взрослый член семьи признаёт общее правило очереди, но говорит о своём дворе.', NULL, NULL, 'neutral', NULL, NULL, 'scene.family.before_distribution.opening.bread', 'На складе сказали: очередь общая. Я не спорю. Только пустая полка у каждого своя.', 'Вторая реплика открытия непосредственно перед вариантами ответа; говорящий не предъявляет права перед другими дворами.', 'Общая очередь не отменяет разной нужды семей.', 'Завершить просьбу без упрёка соседям и без торга.', 'Сохранить контраст общей очереди и отдельной полки; не менять его на обвинение кладовщика.', 'manual/quests/family-thread.md#разговор-до-выдачи', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.reply.general', 'scene.family.before_distribution', 'scene', 'dialogue', 'member', 'chairman', 'Взрослый член семьи отвечает после принятого общего правила.', NULL, NULL, 'neutral', 'Выбран answer.general.', NULL, 'scene.family.before_distribution.answer.general', 'Значит, просьба была первая, а паёк получат все.', 'Ответ на общую помощь; «все» означает только все дворы у принятого порога, не всё население.', 'Проситель осознаёт, что помощь распространилась дальше его двора.', 'Подтвердить принятое правило, не присваивая себе заслугу.', 'Сохранить различие «первая просьба» и «всем подходящим»; не расширять до всех жителей.', 'manual/quests/family-thread.md#разговор-до-выдачи', 1, NULL, 0, 41);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.reply.personal', 'scene.family.before_distribution', 'scene', 'dialogue', 'member', 'chairman', 'Взрослый член семьи отвечает после личной помощи их двору.', NULL, NULL, 'neutral', 'Выбран answer.personal.', NULL, 'scene.family.before_distribution.answer.personal', 'Спасибо. За чужой двор я не отвечу, а свой до выдачи доведу.', 'Ответ после решения о личном пайке; говорящий не распоряжается другими дворами.', 'Семья благодарит и берёт ответственность за собственный двор.', 'Закрыть разговор без требования помочь соседям тем же способом.', 'Сохранить благодарность без долгового обещания или укора соседям.', 'manual/quests/family-thread.md#разговор-до-выдачи', 1, NULL, 0, 40);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.reply.premium', 'scene.family.before_distribution', 'scene', 'dialogue', 'member', 'chairman', 'Взрослый член семьи принимает заслуженную премию.', NULL, NULL, 'neutral', 'Выбран answer.premium.', NULL, 'scene.family.before_distribution.answer.premium', 'За дело возьмём. И детям скажу, чем заработано.', 'Ответ после премии за уже совершённое дело; в семье действительно есть ребёнок.', 'Семья принимает премию как признание труда, не как подачку.', 'Закрыть ветку премии достойно и конкретно.', 'Сохранить «за дело» и сообщение детям; не называть премию благотворительностью.', 'manual/quests/family-thread.md#разговор-до-выдачи', 1, NULL, 0, 42);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.reply.unchanged', 'scene.family.before_distribution', 'scene', 'dialogue', 'member', 'chairman', 'Взрослый член семьи принимает ясный ответ об обычной выдаче.', NULL, NULL, 'neutral', 'Выбран answer.unchanged.', NULL, 'scene.family.before_distribution.answer.unchanged', 'Значит, до выдачи — своим двором. Ответ ясен.', 'Ответ только после явного отказа менять порядок; при вышедшем сроке разговора и этой реплики нет.', 'Семья понимает, что до обычной выдачи рассчитывает на себя.', 'Закрыть разговор без унижения или скрытого штрафа.', 'Сохранить спокойную дистанцию, не превращать строку в благодарность или угрозу.', 'manual/quests/family-thread.md#разговор-до-выдачи', 1, NULL, 0, 43);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.night_hunt.distiller_leak_return.opening.new_place', 'scene.night_hunt.distiller_leak_return', 'scene', 'dialogue', 'storekeeper', 'chairman', 'Работник склада сообщает известное место новой передачи.', NULL, NULL, 'neutral', 'После повторной утечки; работнику известно новое наблюдение передачи.', NULL, 'scene.night_hunt.distiller_leak_return.opening.through_yard', 'Вчера передача была уже {place}. Там и посмотрите вечером.', 'Дополнение дневного доклада перед новой вечерней засадой, не вывод из одной недостачи.', 'Названо новое место известной свидетелю передачи; старый двор не считается верным автоматически.', 'Дать маршрут следующего поиска без раскрытия тайной роли.', 'Показывать только при действительно известном работнику наблюдении. Повторная утечка сама адреса не раскрывает.', 'manual/texts/night-hunt-scenes.md#склад-остался-проходным--повторная-утечка', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.night_hunt.distiller_leak_return.opening.through_yard', 'scene.night_hunt.distiller_leak_return', 'scene', 'dialogue', 'storekeeper', 'chairman', 'Работник склада сообщает председателю о новой утечке после поимки самогонщика.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Того у ворот взяли, а мешки опять ушли. Значит, человек сменился, а склад так и остался проходным двором.', 'Днём в кабинете после новой фактической утечки при всё ещё открытом складе; самогонщик уже был пойман у ворот.', 'Поимка убрала одного продавца, но не закрыла путь сырья со склада к следующему.', 'Перенести внимание игрока с личности пойманного на охрану склада без доноса на конкретного работника.', 'Сохранить противопоставление сменившегося человека и неизменившегося проходного двора; «проходной двор» относится к складу.', 'manual/texts/night-hunt-scenes.md#склад-остался-проходным--повторная-утечка', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.night_hunt.distiller_report.answer.decline', 'scene.night_hunt.distiller_report', 'scene', 'choice', 'chairman', 'storekeeper', 'Председатель пока отказывается от вечерней засады.', 'answer', NULL, 'neutral', NULL, NULL, 'scene.night_hunt.distiller_report.opening.meeting', 'Сегодня вечером не пойду.', 'Второй из двух ответов председателя в дневном разговоре.', 'Председатель не берёт нынешнюю засаду, но причина в мире остаётся.', 'Отложить действие без наказания и без обещания конкретной следующей даты.', 'Сохранить прямоту и вечер как время предлагаемой засады.', 'manual/texts/night-hunt-scenes.md#кто-гонит--пропавшее-сырьё', 1, NULL, 0, 31);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.night_hunt.distiller_report.answer.take', 'scene.night_hunt.distiller_report', 'scene', 'choice', 'chairman', 'storekeeper', 'Председатель берёт вечернюю засаду на себя.', 'answer', NULL, 'neutral', NULL, NULL, 'scene.night_hunt.distiller_report.opening.meeting', 'Сегодня вечером, как стемнеет, проверю на месте.', 'Первый из двух ответов председателя в дневном разговоре.', 'Председатель обещает прийти после наступления темноты, но до ночного отбоя.', 'Назначить вечернюю засаду без лунного календаря и без обещания ночного разговора.', 'Сохранить оба признака времени: сегодня вечером и после наступления темноты.', 'manual/texts/night-hunt-scenes.md#кто-гонит--пропавшее-сырьё', 1, NULL, 0, 30);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.night_hunt.distiller_report.opening.meeting', 'scene.night_hunt.distiller_report', 'scene', 'dialogue', 'storekeeper', 'chairman', 'Работник склада сообщает только то, что видел сам.', NULL, NULL, 'neutral', NULL, NULL, 'scene.night_hunt.distiller_report.opening.mice', 'Позавчера, уже затемно, {place} двое встретились. Один пришёл с пустыми руками, ушёл — уже не с пустыми. Я туда не полез. Моё дело склад удержать.', 'Тот же дневной разговор после показа листка выдач.', 'Работник передаёт известное ему место наблюдения у ворот определённого двора, не имя тайного самогонщика.', 'Дать место для вечерней проверки, не превращая наблюдение в готовое доказательство.', 'Сохранить противопоставление пустых рук до встречи и непустых после; «моё дело склад удержать» не является признанием в утечке.', 'manual/texts/night-hunt-scenes.md#кто-гонит--пропавшее-сырьё', 3, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.night_hunt.distiller_report.opening.mice', 'scene.night_hunt.distiller_report', 'scene', 'dialogue', 'storekeeper', 'chairman', 'Работник склада показывает председателю необъяснённую недостачу.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'На мышей я сперва списал. Только мышь нынче разборчивая: зерно берёт, мешок завязывает и со двора уносит.', 'Днём в кабинете; внизу листка выдач приписаны три мешка без накладной.', 'Недостача похожа не на порчу и не на грызунов, а на аккуратный вынос целых мешков.', 'Сообщить о хозяйственной дыре сухой наблюдательной шуткой, а не обвинением.', 'Сохранить образ разборчивой мыши, которая завязывает мешок и уносит его со двора.', 'manual/texts/night-hunt-scenes.md#кто-гонит--пропавшее-сырьё', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.night_hunt.distiller_report.reply.decline', 'scene.night_hunt.distiller_report', 'scene', 'dialogue', 'storekeeper', 'chairman', 'Работник склада принимает отказ председателя без обиды.', NULL, NULL, 'neutral', 'Выбран answer.decline.', NULL, 'scene.night_hunt.distiller_report.answer.decline', 'Значит, ещё раз пересчитаю. Может, мешки сами образумятся.', 'После отказа председателя от нынешней вечерней засады.', 'Работник продолжит учёт, хотя понимает, что один пересчёт утечку не закроет.', 'Закрыть разговор хозяйственной досадой, а не упрёком игроку.', 'Сохранить шутку на стороне учёта: образумиться должны исчезающие мешки, не человек.', 'manual/texts/night-hunt-scenes.md#кто-гонит--пропавшее-сырьё', 1, NULL, 0, 41);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.night_hunt.distiller_report.reply.take', 'scene.night_hunt.distiller_report', 'scene', 'dialogue', 'storekeeper', 'chairman', 'Работник склада объясняет границу своего участия.', NULL, NULL, 'neutral', 'Выбран answer.take.', NULL, 'scene.night_hunt.distiller_report.answer.take', 'Место я назвал. Засветло дорогу запомните. Как стемнеет — дальше без меня.', 'После согласия председателя на вечернюю засаду.', 'Место уже названо в свидетельстве; работник советует запомнить дорогу засветло, не обещает несуществующее сопровождение.', 'Оставить перехват личным действием председателя без трусости и доносительства работника.', 'Сохранить вечер после темноты до отбоя, личный приход председателя и границу участия работника. Не добавлять метку или сопровождение.', 'manual/texts/night-hunt-scenes.md#кто-гонит--пропавшее-сырьё', 2, NULL, 0, 40);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.perk.talk_to_people_close.thought', 'scene.perk.talk_to_people_close', 'scene', 'narration', 'chairman', NULL, 'Председатель мысленно отмечает конкретный результат только что прошедшего разговора.', NULL, NULL, 'neutral', 'Первый разговор с результатом; quest_perk_03 закрылся.', NULL, NULL, 'Дело сдвинулось не приказом. Значит, услышали.', 'Внутренняя мысль после первого разговора, который привёл к согласию, снятию просьбы или улаженной ссоре.', 'Дело изменилось после разговора, но одна удача не делает председателя убедительным навсегда.', 'Отметить человеческий смысл уже рассчитанного закрытия перка, не выдавая новый результат самой репликой.', 'Не называть харизму и не обещать постоянной способности убеждать.', 'manual/texts/perk-entry-quests.md#поговорить-с-людьми', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.perk.talk_to_people_open.thought', 'scene.perk.talk_to_people_open', 'scene', 'narration', 'chairman', NULL, 'Председатель мысленно оценивает результат только что прошедшего разговора.', NULL, NULL, 'neutral', 'Первый разговор без результата; quest_perk_03 открылся.', NULL, NULL, 'Слова были мои. Решение осталось прежним. Значит, разговора не получилось.', 'Внутренняя мысль после первого безрезультатного разговора; звучит в уже идущем диалоге без новой постановки.', 'Собеседник сохранил своё решение; дело не изменилось.', 'Дать игроку человеческую формулировку первого неудачного опыта разговора без штрафа и обвинения жителя.', 'Не добавлять новую сцену разговора, не понижать метрику и не называть собеседника упрямым.', 'manual/texts/perk-entry-quests.md#поговорить-с-людьми', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.school_fears.birds_settle.notebook', 'scene.school_fears.birds_settle', 'scene', 'document', NULL, NULL, NULL, NULL, NULL, 'neutral', 'society_outcome=observation', NULL, NULL, 'Птицы сели все сразу. На уроке сказали — на ночёвку. Старшие сказали — потому что наговорились. Проверить не удалось.', '«Чёрное облако», сцена «Птицы сели»; строка авторского источника 375.', 'После развязки дети всё ещё могут искать близости взрослого.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 1, NULL, 0, 40);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.school_fears.birds_settle.older_agrees', 'scene.school_fears.birds_settle', 'scene', 'dialogue', 'older', NULL, 'Присутствующие дети и взрослые говорят между собой.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Можно. Мы же не на испытании.', '«Чёрное облако», сцена «Птицы сели»; строка авторского источника 374.', 'После развязки дети всё ещё могут искать близости взрослого.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 1, NULL, 0, 30);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.school_fears.birds_settle.older_explains', 'scene.school_fears.birds_settle', 'scene', 'dialogue', 'older', NULL, 'Присутствующие дети и взрослые говорят между собой.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Оно никого не выбирает. Смотрите: сейчас повернёт, потом сядет.', '«Чёрное облако», сцена «Птицы сели»; строка авторского источника 372.', 'После развязки дети всё ещё могут искать близости взрослого.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.school_fears.birds_settle.younger_checks', 'scene.school_fears.birds_settle', 'scene', 'dialogue', 'younger', NULL, 'Присутствующие дети и взрослые говорят между собой.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'А ближе встать всё равно можно?', '«Чёрное облако», сцена «Птицы сели»; строка авторского источника 373.', 'После развязки дети всё ещё могут искать близости взрослого.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.school_fears.count_cloud.adult_admits', 'scene.school_fears.count_cloud', 'scene', 'dialogue', 'adult', NULL, 'Присутствующие дети и взрослые говорят между собой.', NULL, NULL, 'neutral', 'quest_outcome=observe_with_source; secret=early_home', NULL, NULL, 'История про крышу — моя. Она, как видите, на месте.', '«Чёрное облако», сцена «Посчитать облако»; строка авторского источника 300.', 'Дети видят птиц вместо чудовища, без проверки на храбрость.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 1, NULL, 0, 50);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.school_fears.count_cloud.older_admits', 'scene.school_fears.count_cloud', 'scene', 'dialogue', 'older', NULL, 'Присутствующие дети и взрослые говорят между собой.', NULL, NULL, 'neutral', 'quest_outcome=observe_with_source; secret=borrowed_name', NULL, NULL, 'Про крышу — моя выдумка. Из облака лучше выходило.', '«Чёрное облако», сцена «Посчитать облако»; строка авторского источника 301.', 'Дети видят птиц вместо чудовища, без проверки на храбрость.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 1, NULL, 0, 60);
